const t=[{id:"suggestion-S01",title:"Peerdeman et al. · 2016 · Erwartungen beeinflussen das Schmerzerleben von Patienten",url:"https://cris.maastrichtuniversity.nl/ws/files/76691125/Peters_2016_Relieving_patients_with_expectation_interventions.pdf",type:"research",finding:"27 zusammengefasste Studien mit 1.256 ausgewählten Patienten fanden nach Erwartungsinterventionen weniger selbst berichtete Schmerzen: g = 0,61, 95%-Konfidenzintervall 0,42 bis 0,79; nach Verzerrungskorrektur 0,43, 0,24 bis 0,62.",limitation:"Klinische Interventionen unterscheiden sich von einem selbst geschriebenen Satz. Große Unterschiede zwischen Studien; weniger berichteter Schmerz heilt nicht seine Ursache. Die Sensitivitätsschätzung für Angst nach Ausschluss eines Ausreißers war 0,03, Intervall −0,21 bis 0,26."},{id:"suggestion-S02",title:"Epton et al. · 2015 · Eigene Werte bekräftigen und Gesundheitsverhalten",url:"https://research.manchester.ac.uk/en/publications/the-impact-of-self-affirmation-on-health-behavior-change-a-meta-a/",type:"research",finding:"Das Bekräftigen eigener Werte zusammen mit Gesundheitsinformationen zeigte in 144 Ergebnistests kleine durchschnittliche Unterschiede bei der Annahme der Informationen, Absichten und Verhalten. Verhalten: d = 0,32, 95%-Konfidenzintervall 0,19 bis 0,44.",limitation:"144 Tests sind nicht zwingend verschiedene Studien. Die Teilnehmerzahlen einzelner Ergebnisse überschneiden sich. Daraus folgen keine belegten Wirkungen von Wertetexten allein, wiederholtem Selbstlob oder ODAs kurzer Erwachsenenübung."},{id:"suggestion-S03",title:"Kross et al. · 2014 · Mit Abstand über sich selbst nachdenken",url:"https://rascl.studentorg.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Sieben kurze Experimente umfassten 585 Personen. In Studie 2 dachte man drei Minuten vor einem Gespräch mit dem eigenen Namen oder ohne Ich-Perspektive nach. Beobachtende bewerteten die Gesprächsleistung besser.",limitation:"Meist Studierende und Situationen sozialer Bewertung. Angst vor dem Gespräch besserte sich in Studie 2 nicht signifikant; die Erholung danach war deutlicher. ODAs kürzere Verbindung von Rat und Handlung ist keine Behandlung und garantiert keine Wirkung."},{id:"suggestion-S04",title:"Hatzigeorgiadis et al. · 2011 · Selbstgespräche und sportliche Leistung",url:"https://doi.org/10.1177/1745691611413136",type:"research",finding:"32 Studien, 62 Effekte und 2.741 Teilnehmende fanden im Durchschnitt einen Leistungsvorteil bei Sportaufgaben: d+ = 0,48, 95%-Konfidenzintervall 0,38 bis 0,58. Schätzungen für Aufgaben- und Trainingsgruppen unterschieden sich.",limitation:"Einige Studien hatten keine Kontrollgruppe. Vergleiche von Studienmerkmalen belegen weder die optimale Dosis noch einen allgemeinen Vorrang von Anweisungen. Die Übertragung auf Büroarbeit und Gallweys gesamter Ansatz wurden nicht geprüft."},{id:"suggestion-S05",title:"Zhang et al. · 2025 · Selbstbekräftigung und Wohlbefinden",url:"https://hub.hku.hk/handle/10722/366517",type:"research",finding:"Die institutionelle Zusammenfassung berichtet über 67 Artikel und 129 unabhängige Tests mit nichtklinischen Gruppen. Im Durchschnitt gab es kleine Vorteile bei Selbstwahrnehmung und Wohlbefinden.",limitation:"Vollständige Methoden, Gesamtzahl der Teilnehmenden, Konfidenzintervalle, genaue Effektkennzahl und Nachbeobachtungsdauer waren nicht verfügbar. Das validiert nicht jeden Bekräftigungssatz oder ein bestimmtes Ritual."},{id:"suggestion-S06",title:"Wang, Wang & Gai · 2021 · Ergebnis, Hindernis und Reaktion planen",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 Artikel, 24 unabhängige Effekte und 15.907 Teilnehmende fanden einen durchschnittlichen Vorteil bei der Zielerreichung durch mentales Kontrastieren mit Wenn-dann-Plänen: g = 0,336, Intervall 0,229 bis 0,443; nach Verzerrungskorrektur 0,242, 0,143 bis 0,342.",limitation:"Methoden und Kontrollbedingungen unterschieden sich. Das validiert weder die zusammengesetzte ODA-Karte noch positive Worte als wirksamen Bestandteil oder die Trennung von Abendfantasie und Planung am nächsten Morgen."},{id:"suggestion-S07",title:"Wood, Perunovic & Lee · 2009 · Positive Aussagen über sich selbst",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Die Zusammenfassung berichtet unmittelbar schlechtere Reaktionen bei einigen Teilnehmenden mit geringem Selbstwertgefühl, die einen stark positiven Satz wiederholten. Bei höherem Selbstwertgefühl waren Vorteile begrenzt.",limitation:"Ursprüngliche Teilnehmerzahlen, Wiederholungszahl und numerische Effekte ließen sich nicht bestätigen. Zwei spätere Studien fanden das Muster nicht wieder. Weder eine klinische Schwelle noch ein allgemeiner Mechanismus für unpassende Sätze ist belegt."},{id:"suggestion-S08",title:"Flynn & Bordieri · 2020 · Wiederholungsstudien zu positiven Bekräftigungen",url:"https://contextualscience.org/publications/flynn_bordieri_2020",type:"research",finding:"Zwei Experimente mit universitären Gruppen, etwa 225 und 237 Teilnehmenden, fanden das vorhergesagte Muster für Stimmung, momentanes Selbstwertgefühl oder dessen Abhängigkeit vom grundsätzlichen Selbstwertgefühl nicht wieder.",limitation:"Nur die Zusammenfassung der Autoren war verfügbar. Numerische Effekte, Konfidenzintervalle und Genauigkeit waren nicht zugänglich. Ein Nullbefund belegt weder allgemeinen Nutzen noch allgemeine Harmlosigkeit."},{id:"suggestion-S09",title:"Lally et al. · 2010 · Gewohnheiten im Alltag",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"96 Freiwillige wiederholten 84 Tage lang Ess-, Trink- oder Bewegungsverhalten in wiederkehrenden Situationen. Bei 39 ausreichend passenden Modellen unterschied sich die geschätzte Zeit bis zur Automatisierung deutlich.",limitation:"Beobachtungsstudie, kein Test von Bekräftigungssätzen. Die geschätzten 66 Tage im Median sind keine Frist; manche Schätzungen reichen über die Beobachtung hinaus. Kein Beleg für Automatisierung bis Freitag oder dauerhafte Änderung nach 21 Tagen."},{id:"suggestion-S10",title:"Paller, Creery & Schechtman · 2021 · Gedächtnis und Schlaf",url:"https://faculty.wcas.northwestern.edu/paller/AnnRev2021.pdf",type:"research",finding:"Die Übersichtsarbeit behandelt die erneute Aktivierung schon gelernter Inhalte im Schlaf und begrenztes Lernen einfacher Verknüpfungen während des Schlafens.",limitation:"Erzählende Übersichtsarbeit ohne gemeinsamen Effektwert. Gedächtnisverarbeitung belegt weder besondere Empfänglichkeit für Selbsthilfebefehle beim Einschlafen noch Murphys Ritual, komplexe Fähigkeiten durch Aufnahmen oder gedanklich gesteuerte Ergebnisse."},{id:"suggestion-S11",title:"Cohen et al. · 2006 · Über Werte schreiben an einer Schule",url:"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/cohen_et_al._2006_-_reducing_the_racial_achievement_gap.pdf",type:"research",finding:"Zwei randomisierte Feldexperimente umfassten 243 Siebtklässler an einer US-Schule. Etwa fünfzehn Minuten über Werte zu schreiben verbesserte dort die Noten Schwarzer Schüler im untersuchten Fach.",limitation:"Kein signifikanter Effekt bei weißen Schülern. Eine spätere große Wiederholungsstudie fand keinen signifikanten Nutzen. Daraus folgen weder allgemeine Lernvorteile noch Zuversicht bei Erwachsenen oder eine sofortige Stimmungswirkung."},{id:"suggestion-S12",title:"Hanselman et al. · 2017 · Große Wiederholungsstudie zur Wertebekräftigung",url:"https://files.eric.ed.gov/fulltext/ED578033.pdf",type:"research",finding:"Eine Wiederholungsstudie mit einer neuen Gruppe an mehreren Mittelstufenschulen fand keinen signifikanten Vorteil beim untersuchten Notendurchschnitt. Ihre Genauigkeit reichte aus, Vorteile von mindestens 0,10 Standardabweichungen auszuschließen.",limitation:"Schulumfeld und gemessenes Ergebnis zählen. Das zeigt nicht, dass jede Wertebetrachtung nutzlos ist, und widerlegt keine Befunde zu Gesundheitsinformationen. Der verlinkte Text ist ein angenommenes Manuskript."},{id:"suggestion-S13",title:"Toth et al. · 2020 · Gedankliches Üben und Leistung",url:"https://pure.ul.ie/en/publications/does-mental-practice-still-enhance-performance-a-24-year-follow-u/",type:"research",finding:"Die institutionelle Zusammenfassung berichtet 37 Aufgaben- und Fertigkeitsstudien sowie einen kleinen Leistungszusammenhang nach Korrektur möglicher Publikationsverzerrung, r = 0,131.",limitation:"Vollständige Methoden, Gesamtzahl der Teilnehmenden und Konfidenzintervall waren nicht zugänglich. Aufgaben im Kopf zu üben validiert weder Autosuggestion vor dem Schlafen noch ein Markenritual oder eine allgemeine Übungsdosis."},{id:"suggestion-S15",title:"Émile Coué · Englische Ausgabe 1922 · Bewusste Autosuggestion",url:"https://www.gutenberg.org/cache/epub/27203/pg27203-images.html",type:"technique",finding:"Der historische Text empfiehlt zwanzig Wiederholungen mit leiser Stimme nach dem Aufwachen und vor dem Schlafen. Knoten dienen zum Zählen; man spricht mit geschlossenen Augen und ohne Anstrengung.",limitation:"Anekdoten und Erfahrungsberichte sind keine kontrollierten Belege. Zwanzig Wiederholungen sind eine historische Vorgabe, keine bewiesene Dosis. Allgemeine Gesetze zur Vorstellungskraft und Heilungsversprechen des Textes sind unbelegt."},{id:"suggestion-S16",title:"Joseph Murphy · Die Macht Ihres Unterbewusstseins · Verlagsbeschreibung",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"Die Beschreibung belegt die Herkunft des Buches und seine Werbung für Glauben und Vorstellungskraft.",limitation:"Keine Studienbelege angegeben. Genaue Abendformel, Glückwunschszene und Dankbarkeitspassage wurden nicht überprüft. Forschung zu Schlaf und Gedächtnis validiert weder einen Vorteil beim Eindösen noch Anziehung durch das Unterbewusstsein oder Heilung."},{id:"suggestion-S17",title:"Oettingen et al. · 2015 · Mentales Kontrastieren und Zeitplanung",url:"https://doi.org/10.1002/ejsp.2090",type:"research",finding:"Studie 1 nutzte eine Sitzung: gewünschtes Ergebnis, Hindernis und Reaktion benennen, einen Wenn-dann-Plan mit üblicher Zeit und Ort ergänzen und dann die Woche planen.",limitation:"Deutsche Studierende; das geprüfte Ergebnis waren eingeplante Stunden, keine erledigte Arbeit. Weder eine feste Minutendosis noch ein besonderer Zeitpunkt vor dem Schlafen wurde belegt."},{id:"suggestion-S18",title:"Louise Hay · Was ist Spiegelarbeit?",url:"https://www.louisehay.com/what-is-mirror-work/",type:"technique",finding:"Die Website der Autorin beschreibt positive Sätze vor dem Spiegel und ein Programm über 21 Tage.",limitation:"Herkunft eines Praxisansatzes, kein Wirksamkeitsbeleg. Die Dossierrecherche fand keine kontrollierte Studie zum Gesamtprogramm; das ist eine Recherchegrenze. Weder ein Vorrang des Spiegels noch eine Gewohnheitsfrist von 21 Tagen ist belegt."},{id:"suggestion-S19",title:"Joe Dispenza · Ein neues Ich · Ausgabe laut Verlag",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/9781401938093/",type:"technique",finding:"Der Verlag datiert das Taschenbuch auf Februar 2013. Das E-Book erschien erstmals 2012.",limitation:"Werbliche Beschreibung, keine kontrollierten Belege. Die genaue Zehn-Minuten-Routine, Dankbarkeitsfolge und das Änderungssignal wurden nicht überprüft. Quantenanziehung, genetische Befehle und Heilung sind nicht belegt."},{id:"suggestion-S20",title:"NIMH · Hilfe bei psychischen Erkrankungen",url:"https://www.nimh.nih.gov/health/find-help",type:"guidance",finding:"Die offizielle Orientierung beschreibt Wege zu fachlicher Unterstützung bei psychischen Problemen und Krisen. Anhaltende Belastung, starke Beeinträchtigung und Selbstverletzungsgedanken erfordern passende Hilfe.",limitation:"ODA stellt keine Diagnose und bietet keine Behandlung. Außerhalb der USA nutze örtliche Angebote. Besorgniserregende körperliche Symptome müssen medizinisch abgeklärt werden. Selbstgespräche dürfen Missbrauch und reale Gefahr nicht als sicher umdeuten."},{id:"murphy-subconscious",title:"Joseph Murphy · Die Macht Ihres Unterbewusstseins · Verlagsbeschreibung",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"Die Beschreibung belegt die Herkunft des Buches und seine Werbung für Glauben und Vorstellungskraft.",limitation:"Keine Studienbelege angegeben. Genaue Abendformel, Glückwunschszene und Dankbarkeitspassage wurden nicht überprüft. Forschung zu Schlaf und Gedächtnis validiert weder einen Vorteil beim Eindösen noch Anziehung durch das Unterbewusstsein oder Heilung."},{id:"expectation-suggestion",title:"Peerdeman et al. · 2016 · Erwartungen beeinflussen das Schmerzerleben von Patienten",url:"https://cris.maastrichtuniversity.nl/ws/files/76691125/Peters_2016_Relieving_patients_with_expectation_interventions.pdf",type:"research",finding:"27 zusammengefasste Studien mit 1.256 ausgewählten Patienten fanden nach Erwartungsinterventionen weniger selbst berichtete Schmerzen: g = 0,61, 95%-Konfidenzintervall 0,42 bis 0,79; nach Verzerrungskorrektur 0,43, 0,24 bis 0,62.",limitation:"Klinische Interventionen unterscheiden sich von einem selbst geschriebenen Satz. Große Unterschiede zwischen Studien; weniger berichteter Schmerz heilt nicht seine Ursache. Die Sensitivitätsschätzung für Angst nach Ausschluss eines Ausreißers war 0,03, Intervall −0,21 bis 0,26."},{id:"positive-self-statements",title:"Wood, Perunovic & Lee · 2009 · Positive Aussagen über sich selbst",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Die Zusammenfassung berichtet unmittelbar schlechtere Reaktionen bei einigen Teilnehmenden mit geringem Selbstwertgefühl, die einen stark positiven Satz wiederholten. Bei höherem Selbstwertgefühl waren Vorteile begrenzt.",limitation:"Ursprüngliche Teilnehmerzahlen, Wiederholungszahl und numerische Effekte ließen sich nicht bestätigen. Zwei spätere Studien fanden das Muster nicht wieder. Weder eine klinische Schwelle noch ein allgemeiner Mechanismus für unpassende Sätze ist belegt."},{id:"self-affirmation-health",title:"Epton et al. · 2015 · Eigene Werte bekräftigen und Gesundheitsverhalten",url:"https://research.manchester.ac.uk/en/publications/the-impact-of-self-affirmation-on-health-behavior-change-a-meta-a/",type:"research",finding:"Das Bekräftigen eigener Werte zusammen mit Gesundheitsinformationen zeigte in 144 Ergebnistests kleine durchschnittliche Unterschiede bei der Annahme der Informationen, Absichten und Verhalten. Verhalten: d = 0,32, 95%-Konfidenzintervall 0,19 bis 0,44.",limitation:"144 Tests sind nicht zwingend verschiedene Studien. Die Teilnehmerzahlen einzelner Ergebnisse überschneiden sich. Daraus folgen keine belegten Wirkungen von Wertetexten allein, wiederholtem Selbstlob oder ODAs kurzer Erwachsenenübung."},{id:"distanced-self-talk",title:"Kross et al. · 2014 · Mit Abstand über sich selbst nachdenken",url:"https://rascl.studentorg.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Sieben kurze Experimente umfassten 585 Personen. In Studie 2 dachte man drei Minuten vor einem Gespräch mit dem eigenen Namen oder ohne Ich-Perspektive nach. Beobachtende bewerteten die Gesprächsleistung besser.",limitation:"Meist Studierende und Situationen sozialer Bewertung. Angst vor dem Gespräch besserte sich in Studie 2 nicht signifikant; die Erholung danach war deutlicher. ODAs kürzere Verbindung von Rat und Handlung ist keine Behandlung und garantiert keine Wirkung."},{id:"sport-self-talk",title:"Hatzigeorgiadis et al. · 2011 · Selbstgespräche und sportliche Leistung",url:"https://doi.org/10.1177/1745691611413136",type:"research",finding:"32 Studien, 62 Effekte und 2.741 Teilnehmende fanden im Durchschnitt einen Leistungsvorteil bei Sportaufgaben: d+ = 0,48, 95%-Konfidenzintervall 0,38 bis 0,58. Schätzungen für Aufgaben- und Trainingsgruppen unterschieden sich.",limitation:"Einige Studien hatten keine Kontrollgruppe. Vergleiche von Studienmerkmalen belegen weder die optimale Dosis noch einen allgemeinen Vorrang von Anweisungen. Die Übertragung auf Büroarbeit und Gallweys gesamter Ansatz wurden nicht geprüft."},{id:"sleep-memory-reactivation",title:"Paller, Creery & Schechtman · 2021 · Gedächtnis und Schlaf",url:"https://faculty.wcas.northwestern.edu/paller/AnnRev2021.pdf",type:"research",finding:"Die Übersichtsarbeit behandelt die erneute Aktivierung schon gelernter Inhalte im Schlaf und begrenztes Lernen einfacher Verknüpfungen während des Schlafens.",limitation:"Erzählende Übersichtsarbeit ohne gemeinsamen Effektwert. Gedächtnisverarbeitung belegt weder besondere Empfänglichkeit für Selbsthilfebefehle beim Einschlafen noch Murphys Ritual, komplexe Fähigkeiten durch Aufnahmen oder gedanklich gesteuerte Ergebnisse."},{id:"coue-autosuggestion",title:"Émile Coué · Englische Ausgabe 1922 · Bewusste Autosuggestion",url:"https://www.gutenberg.org/cache/epub/27203/pg27203-images.html",type:"technique",finding:"Der historische Text empfiehlt zwanzig Wiederholungen mit leiser Stimme nach dem Aufwachen und vor dem Schlafen. Knoten dienen zum Zählen; man spricht mit geschlossenen Augen und ohne Anstrengung.",limitation:"Anekdoten und Erfahrungsberichte sind keine kontrollierten Belege. Zwanzig Wiederholungen sind eine historische Vorgabe, keine bewiesene Dosis. Allgemeine Gesetze zur Vorstellungskraft und Heilungsversprechen des Textes sind unbelegt."},{id:"hay-mirror-work",title:"Louise Hay · Was ist Spiegelarbeit?",url:"https://www.louisehay.com/what-is-mirror-work/",type:"technique",finding:"Die Website der Autorin beschreibt positive Sätze vor dem Spiegel und ein Programm über 21 Tage.",limitation:"Herkunft eines Praxisansatzes, kein Wirksamkeitsbeleg. Die Dossierrecherche fand keine kontrollierte Studie zum Gesamtprogramm; das ist eine Recherchegrenze. Weder ein Vorrang des Spiegels noch eine Gewohnheitsfrist von 21 Tagen ist belegt."}],n=[{schemaVersion:2,revision:2,id:"suggestion-1",courseId:"suggestion",locale:"de",title:"Deine innere Kritik braucht eine konkrete Aufgabe",goal:"Wähle eine glaubwürdige Anweisung und nutze sie für einen echten Schritt an deiner Aufgabe.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Dich nutzlos genannt und den Entwurf leer gelassen? Gib diesem Satz eine konkrete Aufgabe.",reason:{id:"suggestion-1-reason",label:"Was hat dich die Kritik gekostet? Welche Handlung zählt jetzt?",kind:"text",maxLength:160,optional:!0,suggestions:["Leere Bewerbung; eine erste Tatsache aufschreiben","Korrektur aufgeschoben; das Datum prüfen","Noch keine Folgen beobachtet"]},why:{id:"suggestion-1-why",label:"Wofür würde dir dieser Schritt diese Woche Raum schaffen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Eine hilfreiche Anweisung sagt, was du tun sollst, etwa „Schreib die erste Tatsache auf“. Selbstlob urteilt darüber, wer du angeblich bist. Die Befunde zu stark positiven Sätzen sind gemischt: Eine frühe Studie fand unmittelbar schlechtere Reaktionen bei einigen Teilnehmenden. Zwei spätere Studien fanden dieses Muster nicht wieder. Neutrale Worte sind keine Diagnose über dich.","Wähle eine echte Aufgabe, die zu deiner Richtung passt. Ersetze das Urteil durch eine Anweisung und erarbeite einen brauchbaren Teil. Sportforschung beweist keinen Nutzen für Büroaufgaben. Halte die Handlung fest und ob die Worte geholfen, Druck gemacht oder nichts verändert haben."],example:{title:"Majas erste Tatsache",text:"Um 14 Uhr sitzt Maja vor ihrem Bewerbungsentwurf. „Ich kann nichts“ kennt sie gut. „Ich bin großartig“ fühlt sich falsch an. Sie versucht es mit „Schreib die erste Tatsache auf“ und schreibt einen brauchbaren Satz über ihre Erfahrung. Sie zweifelt weiterhin. Sie notiert Satz und Zweifel und plant einen weiteren kleinen Versuch. Das Lob wiederholt sie nicht, bis es sich wahr anfühlt."}},move:{invitation:"Benenne deine Aufgabe und Anweisung. Die Vorschläge zeigen Majas Bewerbung als Beispiel.",instructions:["Benenne vor dem Speichern das konkrete Dokument, die Frage oder den Eintrag.","Lies die Anweisung einmal. Erarbeite dann den passenden brauchbaren Teil."],prompts:[],suggestions:{action:["Mit „Erste Tatsache aufschreiben“ einen Bewerbungssatz schreiben","Die Bewerbungsfrage zur Arbeitserfahrung beantworten"],minimum:["Einen sachlichen Satz zur Arbeitserfahrung speichern","Die Antwort zur Arbeitserfahrung speichern"],cue:["Wenn die Mittagspause zu Ende ist","Wenn das Abendessen abgeräumt ist"],place:["An meinem Küchentisch","Im Entwurf meiner Bewerbung"],minutes:[2,1,3],fallback:["Urteil weglassen; einen sachlichen Bewerbungssatz schreiben","Nachfragen, welche Angabe zur Arbeit gebraucht wird"],observation:["Den Bewerbungssatz, den ich tatsächlich gespeichert habe","Ob die Worte halfen oder Druck machten"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Mit „Erste Tatsache aufschreiben“ einen Bewerbungssatz schreiben",minimum:"Einen sachlichen Satz zur Arbeitserfahrung speichern",minutes:2,cueHint:"Wenn die Mittagspause zu Ende ist",placeHint:"An meinem Küchentisch",obstacleHint:"Aus der Anweisung wird wieder ein Urteil",fallbackHint:"Urteil weglassen; einen sachlichen Bewerbungssatz schreiben",observationHint:"Den Bewerbungssatz, den ich tatsächlich gespeichert habe"},stopRule:"Lass Worte weg, die deine Belastung verstärken. Suche bei anhaltender Belastung Unterstützung. Lass besorgniserregende Symptome fachlich abklären.",accessibleAlternative:"Tippe, diktiere oder nutze Hilfe. Eine neutrale Anweisung zur Aufgabe genügt."},result:{question:"Hast du deinen gewählten brauchbaren Teil erarbeitet?",observationPrompt:"Was hast du tatsächlich getan, und was stand im Weg?"},judgment:{primary:{id:"suggestion-1-decision",scenario:"Maja hat zwei Minuten und die Fakten für einen Bewerbungssatz. Lob fühlt sich falsch an. Der Entwurf ist noch leer.",question:"Was passt zu diesem Versuch?",options:[{id:"suggestion-1-praise",text:"Einen freundlicheren positiven Satz nutzen und dann entscheiden, ob sie mit dem Schreiben anfangen kann.",feedback:"Freundliche Worte sind eine persönliche Vorliebe. Sie weiß aber schon, dass Lob sich heute falsch anfühlt. Versuche eine neutrale Anweisung und erarbeite einen brauchbaren Teil, ohne an Selbstlob glauben zu müssen."},{id:"suggestion-1-fact",text:"„Schreib die erste Tatsache auf“ sagen und dann einen brauchbaren Satz für die Bewerbung schreiben.",feedback:"Das benennt eine Handlung in ihrer Hand und probiert sie sofort aus. Der Satz kann helfen, nichts verändern oder Druck machen. Ihr tatsächlicher Text und ihre Erfahrung lassen sich festhalten."},{id:"suggestion-1-picture",text:"Sich eine erfolgreiche Bewerbungsprüfung vorstellen und dann prüfen, ob sie sich bereit zum Schreiben fühlt.",feedback:"Ein Bild kann angenehme Vorbereitung sein, liefert aber nicht den gewählten brauchbaren Teil. Die Fakten liegen vor. Nutze eine Anweisung und versuche die kleine Handlung."}],bestOptionId:"suggestion-1-fact"}},carry:{takeaway:"Gib dem Satz eine Aufgabe. Prüfe ihn anhand deiner tatsächlichen Handlung.",followUp:{questionId:"suggestion-1-return",question:"Was ist bei deiner Handlung passiert? Hat die Anweisung geholfen oder Druck gemacht?",observationPrompt:"Was zeigt dein tatsächlicher Eintrag?",adjustmentPrompt:"Was behältst oder änderst du beim nächsten Startsignal?"}},goDeeper:{sections:[{heading:"Glaubwürdigkeit ist deine Wahl, keine Punkteschwelle",paragraphs:["Die zugängliche Zusammenfassung von Wood und Kollegen berichtete: Ein stark positiver Satz führte bei einigen Teilnehmenden mit geringem Selbstwertgefühl unmittelbar zu schlechteren Reaktionen. Sie liefert nicht genug Einzelheiten, um eine Wiederholungszahl vorzuschreiben oder die Reaktion einer Person vorherzusagen. Zwei spätere Experimente mit universitären Gruppen von Flynn und Bordieri fanden das vorhergesagte Muster nicht wieder. Die Befunde sprechen daher für Unsicherheit. Sie sind keine feststehende Regel, wonach positive Sätze einem bestimmten Menschentyp schaden. (suggestion-S07; suggestion-S08)","Deine Vorliebe liefert trotzdem brauchbare Informationen. Fühlt sich „Ich bin großartig“ falsch an, kannst du „Schreib die erste Tatsache auf“ wählen, den Wortlaut ändern, Wiederholungen weglassen oder aufhören. Eine private Einschätzung der Glaubwürdigkeit kann dir bei den Worten helfen. Hier ist aber keine Punktzahl eine validierte klinische Schwelle. ODA leitet daraus kein Selbstwertgefühl ab und verlangt keine Ermutigung. Fang bei der konkreten Aufgabe an, damit die Worte eine bestimmte Funktion haben."]},{heading:"Andere Worte haben andere Belege",paragraphs:["Hatzigeorgiadis und Kollegen fassten zweiunddreißig Studien zu Selbstgesprächen mit zweiundsechzig Effekten bei Sport- und Bewegungsaufgaben zusammen. Tabelle 1 berichtete 2.741 Teilnehmende. Der durchschnittliche Leistungsvorteil belegt nicht denselben Nutzen beim Bewerbungsschreiben, in Beziehungen oder bei Angst. Einige Studien hatten keine Kontrollgruppe. Vergleiche der Untergruppen beweisen keine allgemeingültige Rangfolge von Anweisungen und motivierenden Worten. (suggestion-S04)","Die heutige neutrale Anweisung und der kleine Textteil sind eine ODA-Anpassung außerhalb dieser Sportbefunde. Der gesamte Kurs wurde nicht als Paket untersucht. Halte getrennt fest, was du gesagt, tatsächlich getan und an Druck erlebt hast. Ein Satz kann glaubwürdig sein, ohne beim Handeln zu helfen. Er kann beim Anfangen helfen, ohne Zweifel zu verringern. Diese Unterschiede geben dir Gründe, ihn beizubehalten, zu ändern oder wegzulassen. So wird nicht jede Wiederholung automatisch zum Fortschritt in Richtung deines gewählten Lebens."]}],sourceIds:["suggestion-S07","suggestion-S08","suggestion-S04"]}},{schemaVersion:2,revision:2,id:"suggestion-2",courseId:"suggestion",locale:"de",title:"Das Ritual endet, wenn die Handlung anfängt",goal:"Verbinde dieselbe sinnvolle Handlung mit einem Startsignal, das tatsächlich vorkommt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Den Satz wiederholt, die Seite noch leer? Lass beim Startsignal die Handlung folgen.",reason:{id:"suggestion-2-reason",label:"Was gab dir die wiederholte Erinnerung, während deine Aufgabe unerledigt blieb?",kind:"text",maxLength:160,optional:!0,suggestions:["Kurz beruhigt; der Entwurf blieb leer","Die Wahl des ersten Satzes vermieden","Bisher kein Versuch nur mit Erinnerungen"],help:"Noch kein Versuch? Überlege, was erneutes Lesen der Erinnerung aufschieben würde."},why:{id:"suggestion-2-why",label:"Wofür würde dir dieser Schritt diese Woche Raum schaffen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Einen Satz und eine Handlung zu wiederholen sind verschiedene Versuche. Eine Gewohnheitsstudie beobachtete Essen, Trinken und Bewegung bei wiederkehrenden Signalen. Automatisierung entwickelte sich unterschiedlich schnell. Bekräftigungssätze wurden nicht geprüft. Coués zwanzig Wiederholungen sind historische Anweisungen, keine bewiesene Dosis.","Prüfe deinen ersten Eintrag. Glaubwürdige Worte, aber kein Anfang? Behalte die Aufgabe bei und wähle ein Ereignis, das eintritt. „Nach dem Mittagessen schreibe ich einen Bewerbungssatz“ verbindet Signal und Handlung. Lies deine Anweisung einmal, wenn es dir hilft, und erarbeite dann den Teil. Material vorzubereiten bleibt Vorbereitung. Schreiben ist der tatsächliche Versuch."],example:{title:"Maja nutzt die Mittagspause",text:"Majas erste Anweisung war glaubwürdig. Am hektischen Morgen vergaß sie sie aber. Sie bleibt bei der Bewerbung und wählt das Ende der Mittagspause als nächstes Signal. Am Küchentisch liest sie einmal „Schreib die erste Tatsache auf“ und schreibt einen brauchbaren Satz. Sie arbeitet nur kurz. Sie hält Signal und Text fest, ohne das schon eine automatische Gewohnheit zu nennen."}},move:{invitation:"Bleib bei deiner Handlung. Die Vorschläge zeigen Majas Mittagspause als Beispiel.",instructions:["Behalte Handlung und Minimum bei. Ändere das Startsignal nur, wenn dein Eintrag es infrage stellt.","Beim ersten Plan: Benenne vor dem Speichern den brauchbaren Text und eine tatsächliche Gelegenheit."],prompts:[],suggestions:{action:["Nach dem Mittagessen einen Satz zur Arbeitserfahrung schreiben","Nach dem Tee die Bewerbungsfrage zur Erfahrung beantworten"],minimum:["Einen sachlichen Satz für die Bewerbung speichern","Die Antwort zur Arbeitserfahrung speichern"],cue:["Wenn die Mittagspause zu Ende ist","Wenn ich meinen Tee abstelle"],place:["An meinem Küchentisch","Im Entwurf meiner Bewerbung"],minutes:[2,1,3],fallback:["Nach dem Abendessen den Satz zur Erfahrung schreiben","Den Bewerbungssatz in der Mittagspause diktieren"],observation:["Ob Startsignal und Bewerbungssatz zustande kamen","Lesen getrennt vom brauchbaren Text"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Nach dem Mittagessen einen Satz zur Arbeitserfahrung schreiben",minimum:"Einen sachlichen Satz für die Bewerbung speichern",minutes:2,cueHint:"Wenn die Mittagspause zu Ende ist",placeHint:"An meinem Küchentisch",obstacleHint:"Das Mittagssignal geht im Trubel unter",fallbackHint:"Nach dem Abendessen den Satz zur Erfahrung schreiben",observationHint:"Ob Startsignal und Bewerbungssatz zustande kamen"},stopRule:"Lass Wiederholungen weg, die belasten oder wach halten. Nötige Versorgung, Erholung und tatsächliche Sicherheit gehen vor.",accessibleAlternative:"Nutze eine schriftliche, gesprochene oder zugängliche Erinnerung. Perlen oder Zählen sind nicht nötig."},result:{question:"Kam dein Startsignal, und hast du den Teil erarbeitet?",observationPrompt:"Was hast du tatsächlich getan, und was stand im Weg?"},judgment:{primary:{id:"suggestion-2-decision",scenario:"Maja hat an drei Tagen morgens eine glaubwürdige Erinnerung gelesen, aber nicht geschrieben. Der Entwurf und Angaben zur Erfahrung liegen bereit. In der Mittagspause ist zuverlässig Zeit für einen Satz.",question:"Was passt zu diesem Versuch?",options:[{id:"suggestion-2-count",text:"Das morgendliche Signal behalten und vor dem Schreiben noch mehr Wiederholungen einbauen.",feedback:"Mehr Wiederholungen prüfen das Lesen des Satzes, nicht den fehlenden Aufgabenbeginn. Ihre Einträge sprechen für ein unpassendes Signal. Nutze die verfügbare Mittagspause für einen tatsächlichen Satz."},{id:"suggestion-2-cue",text:"Glaubwürdige Worte behalten, die Mittagspause als Signal nutzen und einen Satz schreiben.",feedback:"Das ändert die Bedingung, die Handeln verhindert hat, und behält die sinnvolle Aufgabe bei. Halte fest, ob das Signal kam und der Satz entstand. Automatisierung ist nicht nötig."},{id:"suggestion-2-prepare",text:"Die Mittagspause nutzen, um die Erinnerung zu verbessern und Material für morgen bereitzulegen.",feedback:"Vorbereitung kann fehlende Mittel bereitstellen. Material und Anweisung sind aber schon da. Eine weitere Vorbereitungseinheit würde denselben brauchbaren Satz weiterhin unerledigt lassen."}],bestOptionId:"suggestion-2-cue"}},carry:{takeaway:"Verbinde das Startsignal mit der Handlung, nicht nur mit den Worten davor.",followUp:{questionId:"suggestion-2-return",question:"Führte dein Signal zur Handlung oder Bitte, oder hast du nur die Erinnerung gelesen?",observationPrompt:"Was zeigt dein tatsächlicher Eintrag?",adjustmentPrompt:"Was behältst oder änderst du beim nächsten Startsignal?"}},goDeeper:{sections:[{heading:"Was Coués Zählvorgabe tatsächlich belegt",paragraphs:["Coués englischer Text von 1922 gibt historische Anweisungen: zwanzig Wiederholungen mit leiser Stimme nach dem Aufwachen und vor dem Schlafen, mit geschlossenen Augen und Knoten zum Zählen. Er enthält Anekdoten, Vorführungen und Erfahrungsberichte statt kontrollierter Interventionsbelege. Die Zwanzigerzahl und zweimal tägliche Anwendung belegen deshalb die Herkunft, keine wirksame Dosis. Historische Wiederholungsanweisungen sagen dir nicht, ob deine heutigen Worte bei der gewählten Aufgabe helfen. (suggestion-S15)","Du musst das Ritual nicht nachmachen, um eine glaubwürdige Anweisung auszuprobieren. Seine allgemeinen Gesetze über Vorstellungskraft und Willen sowie seine Heilungsbehauptungen folgen nicht aus den Anekdoten. Behalte verordnete Behandlungen bei. Erkläre neue körperliche Symptome nicht mit einem beruhigenden Satz. Die Hauptfrage lautet: Hilft dein gewähltes Signal bei einer sinnvollen Handlung? Einmal lesen ist freiwillige Vorbereitung. Erst die spätere Handlung dient der Aufgabe."]},{heading:"Eine wiederkehrende Situation schafft nicht sofort eine Gewohnheit",paragraphs:["Lally und Kollegen beobachteten sechsundneunzig Freiwillige. Sie wählten ein Ess-, Trink- oder Bewegungsverhalten in einer wiederkehrenden Situation. Vierundachtzig Tage lang erfassten sie Wiederholung und Automatisierung. Zweiundachtzig Personen lieferten genügend Daten. Bei neununddreißig passten die Modelle ausreichend. Ihre geschätzten Zeiten bis zur nahezu maximalen Automatisierung unterschieden sich stark. Manche Schätzungen reichten über die Beobachtung hinaus. Die sechsundsechzig Tage im Median waren keine Frist für jedes Verhalten. (suggestion-S09)","Das war eine Beobachtungsstudie zu Gewohnheiten. Sie prüfte weder Coués Formel noch Abendwiederholungen oder Bewerbungsschreiben. ODAs Mittagssignal und kurzes Minimum sind Gestaltungsentscheidungen. Ein Versuch kann zeigen, dass das Signal kam und ein Teil möglich war. Er kann weder beweisen, dass der Satz den Erfolg verursachte, noch dass die Routine bis Freitag automatisch abläuft. Halte Vorbereitung, Auftreten des Signals und tatsächlichen Aufgabentext getrennt, wenn du morgen deinen Eintrag prüfst."]}],sourceIds:["suggestion-S15","suggestion-S09"]}},{schemaVersion:2,revision:2,id:"suggestion-3",courseId:"suggestion",locale:"de",title:"Trau dich an die Rückmeldung: Was ist dir wichtig?",goal:"Wenn Rückmeldung deine Aufgabe blockiert, verbinde einen gewählten Wert mit einer tatsächlichen Korrektur.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kommentare gemieden, um dein Selbstvertrauen zu schützen? Lass einen Wert die nächste konkrete Korrektur bestimmen.",reason:{id:"suggestion-3-reason",label:"Welche hilfreiche Anmerkung fällt dir schwer, und was kostet das Aufschieben?",kind:"text",maxLength:160,optional:!0,suggestions:["Vage Worte; beim Gegenlesen versteht man mich nicht","Datum fehlt; meine Bewerbung bleibt unvollständig","Vor einer Änderung brauche ich Klarheit","Noch keine brauchbare Rückmeldung bekommen"]},why:{id:"suggestion-3-why",label:"Wofür würde dir dieser Schritt diese Woche Raum schaffen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Über Werte nachzudenken ist etwas anderes als Selbstlob. Forschung verband es mit Gesundheitsinformationen und fand kleine durchschnittliche Vorteile beim Annehmen der Informationen und späteren Verhalten. Es ist nicht belegt, dass eine kurze Wertenotiz allein jede Aufgabe oder deine Stimmung verbessert.","Nutze das, wenn deine Einträge zeigen, dass du Rückmeldung meidest. Bleib bei der Aufgabe. Ein freiwillig gewählter Wert wie Lernen kann eine Korrektur leiten. Nutze „Prüfe diese Angabe“ und berichtige sie oder frage nach. Gemischte Beweggründe und übernommene Verantwortung zählen ebenfalls. Du brauchst weder einen perfekten Grund noch Zustimmung zu jedem Kommentar oder mehr Selbstvertrauen."],example:{title:"Maja nutzt eine Korrektur",text:"Beim Mittagssignal sieht Maja den Kommentar, ihr Bewerbungssatz sei zu vage. Lernen ist ihr wichtig, trotzdem möchte sie das Dokument schließen. Sie nutzt „Füge ein konkretes Beispiel hinzu“ und nennt im Satz eine echte erledigte Aufgabe. Der Entwurf bleibt unfertig. Sie hält die Korrektur fest, statt aus ihrem Wert neues Selbstvertrauen abzuleiten."}},move:{invitation:"Bleib bei deiner Aufgabe. Beispiel: Majas Korrektur nach einer Rückmeldung.",instructions:["Behalte Handlung und Startsignal bei. Benenne den Kommentar und die tatsächliche Korrektur.","Ein Wert kann helfen. Die Handlung ist die Korrektur oder deine Bitte um Klarheit."],prompts:[],suggestions:{action:["Ein Arbeitsbeispiel in den Bewerbungssatz aufnehmen","Nachfragen, welcher Bewerbungssatz mehr Einzelheiten braucht"],minimum:["Den Bewerbungssatz mit einem Beispiel speichern","Die Frage zu fehlenden Bewerbungsdetails abschicken"],cue:["Wenn die Mittagspause zu Ende ist","Wenn die Anmerkung zum Entwurf eintrifft"],place:["An meinem Küchentisch","Im Entwurf meiner Bewerbung"],minutes:[2,1,3],fallback:["Eine bekannte Tatsache ergänzen, ohne mich zu verteidigen","Nachfragen, welche Angabe erklärt werden muss"],observation:["Den korrigierten Satz oder die tatsächliche Rückfrage","Ob ich die passende Rückmeldung genutzt habe"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Ein Arbeitsbeispiel in den Bewerbungssatz aufnehmen",minimum:"Den Bewerbungssatz mit einem Beispiel speichern",minutes:2,cueHint:"Wenn die Mittagspause zu Ende ist",placeHint:"An meinem Küchentisch",obstacleHint:"Ich möchte stattdessen den ganzen Entwurf verteidigen",fallbackHint:"Eine bekannte Tatsache ergänzen, ohne mich zu verteidigen",observationHint:"Den korrigierten Satz oder die tatsächliche Rückfrage"},stopRule:"Setze Grenzen bei feindseliger oder unsicherer Rückmeldung. Wähle bei Bedarf Schutz oder Unterstützung.",accessibleAlternative:"Wähle einen persönlichen Wert, eine neutrale Anweisung oder Hilfe. Über Werte zu schreiben ist freiwillig."},result:{question:"Hast du die Korrektur gemacht oder deine Frage gestellt?",observationPrompt:"Was hast du tatsächlich getan, und was stand im Weg?"},judgment:{primary:{id:"suggestion-3-decision",scenario:"Die Person, die Majas Bewerbung gegenliest, weist in einem sicheren Austausch auf einen vagen Satz hin. Maja hat ein konkretes Beispiel und möchte lernen, fühlt sich aber angegriffen.",question:"Was passt zu diesem Versuch?",options:[{id:"suggestion-3-strengths",text:"Erst ihre Stärken auflisten und dann zum Satz zurückkehren, wenn die Kritik leichter fällt.",feedback:"Über Stärken nachzudenken kann eine persönliche Vorliebe sein. Das brauchbare Beispiel ist aber jetzt verfügbar. Ihr Wert kann eine Korrektur leiten, ohne dass sie sich vorher wohlfühlen muss."},{id:"suggestion-3-correct",text:"„Füge ein Beispiel hinzu“ nutzen und den Satz mit der vorhandenen Tatsache überarbeiten.",feedback:"So wird Lernen zur konkreten Entscheidung bei derselben Aufgabe. Die Korrektur ist beobachtbar. Sie verlangt weder bessere Stimmung noch Zustimmung zu jedem Kommentar."},{id:"suggestion-3-reassure",text:"Vor der einzelnen Korrektur die gegenlesende Person bitten, ihre allgemeine Fähigkeit zu bestätigen.",feedback:"Bestätigung könnte helfen, aber allgemeine Fähigkeit ist nicht die fehlende Information. Nutze den konkreten Kommentar und die vorhandene Tatsache. Frage nur nach, wenn Einzelheiten unklar sind."}],bestOptionId:"suggestion-3-correct"}},carry:{takeaway:"Ein Wert hilft dann, wenn er eine Entscheidung leitet, die du tatsächlich triffst.",followUp:{questionId:"suggestion-3-return",question:"Hast du korrigiert oder um Klarheit gebeten? Welche Einzelheit ist noch unklar?",observationPrompt:"Was zeigt dein tatsächlicher Eintrag?",adjustmentPrompt:"Was behältst oder änderst du beim nächsten Startsignal?"}},goDeeper:{sections:[{heading:"Belege für Wertebetrachtung gelten im jeweiligen Kontext",paragraphs:["Epton und Kollegen fassten Tests zur Selbstbekräftigung zusammen, die mit Gesundheitsinformationen verbunden war. Sie fanden kleine durchschnittliche Effekte auf die Annahme der Informationen, Absichten und Verhalten. Die 144 Tests betreffen verschiedene Ergebnisse und sind nicht zwingend 144 unterschiedliche Studien. Ihre Teilnehmerzahlen dürfen nicht als einzigartige Personen addiert werden. In diesem Umfeld über Werte nachzudenken ist etwas anderes, als Lob zu wiederholen oder vor der Rückmeldung die eigene Großartigkeit zu behaupten. (suggestion-S02)","Eine neuere Übersichtsarbeit von Zhang und Kollegen berichtete kleine Vorteile beim Wohlbefinden über siebenundsechzig Artikel und 129 unabhängige Tests mit nichtklinischen Gruppen hinweg. Die verfügbare institutionelle Zusammenfassung liefert einen breiten Überblick. Die vollständigen Methoden fehlen aber, um genaue Effektkennzahl, Teilnehmerzahl, Konfidenzintervalle und Nachbeobachtungsdauer zu prüfen. Das erweitert den Kontext über Gesundheitsinformationen hinaus. Es belegt keinen Nutzen unserer heutigen kurzen Werte-und-Korrektur-Übung oder eines bestimmten Bekräftigungssatzes. (suggestion-S05)"]},{heading:"Nutze einen Wert, ohne allgemeine Wirkung zu versprechen",paragraphs:["Eine große Wiederholungsstudie an Mittelstufenschulen von Hanselman und Kollegen fand in ihrer neuen Gruppe keinen signifikanten Vorteil beim untersuchten Notendurchschnitt durch Wertebekräftigung. Die berichtete Genauigkeit konnte Vorteile von mindestens 0,10 Standardabweichungen ausschließen. Das macht nicht jede Wertebetrachtung nutzlos und widerlegt keine Befunde zu Gesundheitsinformationen. Es bedeutet, dass Umfeld, Gruppe und Ergebnis zählen. Ein Schulbefund kann Erwachsenen weder Selbstvertrauen noch einen allgemeinen Leistungsschub versprechen. (suggestion-S12)","ODAs praktische Frage ist enger: Hilft dir ein Wert dabei, eine passende Rückmeldung für deine fortlaufende Aufgabe zu nutzen? Eine kurze freiwillige Notiz und diese Korrektur sind Anpassungen. Lernen, Verantwortung für die Familie und ein neuer Job können dir aus mehreren Gründen zugleich wichtig sein. Niemand prüft, wie rein dein Motiv ist. Trenne hilfreiche Rückmeldung von Beleidigungen oder unsicheren Forderungen. Halte die tatsächliche Korrektur oder Bitte um Hilfe fest, statt dich nur positiver zu beschreiben."]}],sourceIds:["suggestion-S02","suggestion-S05","suggestion-S12"]}},{schemaVersion:2,revision:2,id:"suggestion-4",courseId:"suggestion",locale:"de",title:"Nervös? Gib dir klaren Rat",goal:"Blockieren dich Sorgen ums Auftreten? Sprich dich mit Namen an und nutze deinen vorbereiteten Satz.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Dein Punkt steht, doch du kreist um deine Nervosität? Sprich dich an, dann sag deinen Satz.",reason:{id:"suggestion-4-reason",label:"Was gibt dir weiteres Grübeln, und welche Gelegenheit könnte es kosten?",kind:"text",maxLength:160,optional:!0,suggestions:["Worte verbessert; Einladung zur Frage verpasst","Kurz beruhigt; die fertige Frage aufgeschoben","Eine unklare Frage braucht noch Vorbereitung","Noch keine Gelegenheit verpasst"]},why:{id:"suggestion-4-why",label:"Wofür würde dir dieser Schritt diese Woche Raum schaffen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["In kurzen Experimenten mit sozialem Stress dachten Menschen mit ihrem Namen oder „du“ statt „ich“ über sich nach. Eine Studie fand bessere Gesprächsleistung aus Beobachtersicht, aber keine signifikant geringere Angst davor. Ein anderer Blick verlangt nicht, dass deine Nervosität verschwindet.","Wenn Sorgen um dein Auftreten die Aufgabe blockiert haben, behalte dieselben Fakten: Aus „Ich bin vorbereitet und nervös“ wird „Maja ist vorbereitet und nervös“. Ergänze eine hilfreiche Anweisung. Nutze dann deinen Satz im sicheren Gespräch. Behalte eine bisherige Anweisung, wenn sie funktioniert. Nachdenken mit deinem Namen ist freiwillige Vorbereitung. Das Gespräch ist der tatsächliche Versuch."],example:{title:"Maja fragt beim Bewerbungscheck nach",text:"Maja hat eine fertige Bewerbungsfrage. Ihr Mittagseintrag zeigt: Sie analysierte weiter, wie sie klingen würde. Vor einem sicheren Gespräch sagt sie: „Maja ist vorbereitet und nervös. Frage nach dem Beispiel.“ Sie stellt ihre Frage. Die andere Person braucht Zeit für die Antwort. Maja hält das Gespräch und die ausstehende Antwort fest. Kein Pronomen hat ihre Angst weggezaubert."}},move:{invitation:"Behalte deine Handlung. Beispiel: eine Frage beim Bewerbungscheck.",instructions:["Behalte Handlung und Startsignal bei. Darüber nachzudenken ist freiwillige Vorbereitung.","Beim ersten Gespräch: Benenne die konkrete Frage und eine sichere Gelegenheit.","Stelle deine Frage oder nutze den vorbereiteten Satz. Gewohnte Ich-Formulierungen sind möglich."],prompts:[],suggestions:{action:["Nachfragen, welches Arbeitsbeispiel die Bewerbung braucht","Den Bewerbungssatz mit der gegenlesenden Person teilen"],minimum:["Fragen, welches Arbeitsbeispiel noch fehlt","Den Bewerbungssatz zum Gegenlesen abschicken"],cue:["Wenn ich beim Bewerbungscheck Fragen stellen kann","Wenn die Mittagspause zu Ende ist"],place:["Im vereinbarten Gespräch zum Bewerbungscheck","Im Nachrichtenverlauf zum Bewerbungscheck"],minutes:[2,1,3],fallback:["Jetzt fragen: „Welches Arbeitsbeispiel fehlt?“","Die Frage zum Arbeitsbeispiel zum Gegenlesen abschicken"],observation:["Ob ich die Frage zum Arbeitsbeispiel gestellt habe","Die Antwort, auch wenn sie noch aussteht"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Nachfragen, welches Arbeitsbeispiel die Bewerbung braucht",minimum:"Fragen, welches Arbeitsbeispiel noch fehlt",minutes:2,cueHint:"Wenn ich beim Bewerbungscheck Fragen stellen kann",placeHint:"Im vereinbarten Gespräch zum Bewerbungscheck",obstacleHint:"Ich analysiere weiter, statt meine fertige Frage zu stellen",fallbackHint:"Jetzt fragen: „Welches Arbeitsbeispiel fehlt?“",observationHint:"Ob ich die Frage zum Arbeitsbeispiel gestellt habe"},stopRule:"Pausiere unsichere Gespräche. Suche bei anhaltender Belastung oder starker Beeinträchtigung fachliche Unterstützung.",accessibleAlternative:"Nutze einen sicheren schriftlichen, gebärdeten oder unterstützten Satz. Mit deinem Namen nachzudenken bleibt freiwillig."},result:{question:"Hast du deinen vorbereiteten Satz im Gespräch genutzt?",observationPrompt:"Was hast du tatsächlich getan, und was stand im Weg?"},judgment:{primary:{id:"suggestion-4-decision",scenario:"Maja hat eine klare Bewerbungsfrage. Im vereinbarten Gespräch kann sie diese jetzt stellen, bevor es endet. Sie ist nervös und hat bereits kurz nachgedacht.",question:"Was passt zu diesem Versuch?",options:[{id:"suggestion-4-name",text:"Privat noch einmal üben, um den Wortlaut zu verbessern, und erst bei der nächsten Einladung fragen.",feedback:"Eine Probe kann die Worte verbessern. Ihre Frage ist aber schon klar, und das Gespräch endet gleich. Nutze diese sichere Gelegenheit. Mit dem Namen nachzudenken bleibt freiwillig; eine sachliche Ich-Anweisung geht ebenfalls."},{id:"suggestion-4-analyze",text:"Sich die eigene Nervosität zunächst privat ausführlicher erklären und erst danach über die Teilnahme entscheiden.",feedback:"Ausführliches Nachdenken kann bei einer anderen Frage helfen. Hier verlängert es die Vorbereitung. Die Schwierigkeit liegt jetzt darin, den fertigen Satz während der verfügbaren sicheren Gelegenheit zu nutzen."},{id:"suggestion-4-use",text:"„Maja ist vorbereitet und nervös“ nutzen und dann ihre tatsächliche Frage stellen.",feedback:"Das behält die Tatsachen bei und lässt auf Vorbereitung das Gespräch folgen. Die Laborbefunde versprechen keine geringere Angst davor. Halte den tatsächlichen Satz und die Antwort fest."}],bestOptionId:"suggestion-4-use"}},carry:{takeaway:"Ein anderer Blick sollte zu Rat und Handlung führen, nicht zu noch mehr Selbstanalyse.",followUp:{questionId:"suggestion-4-return",question:"Führte der andere Blick zu deinem tatsächlichen Satz oder zu weiterer Vorbereitung?",observationPrompt:"Was zeigt dein tatsächlicher Eintrag?",adjustmentPrompt:"Was behältst oder änderst du beim nächsten Startsignal?"}},goDeeper:{sections:[{heading:"Ändere den Blick, ohne die Tatsachen zu ändern",paragraphs:["Kross und Kollegen führten sieben Experimente mit 585 Personen durch, meist mit Studierenden und in Situationen sozialer Bewertung. In Studie 2 dachten Teilnehmende vor dem Treffen mit einer unbekannten Person drei Minuten allein nach. Die Versuchsgruppe nutzte dabei den eigenen Namen und Pronomen außerhalb der ersten Person; die Vergleichsgruppe „ich“ und „mich“. Beobachtende bewerteten die Gesprächsleistung der Gruppe, die den eigenen Namen nutzte besser. Angst vor dem Gespräch verringerte sich nicht signifikant. Die Erholung danach war deutlicher. (suggestion-S03)","Ein ehrliches Beispiel hält den Inhalt gleich. Vergleiche „Ich bin vorbereitet und nervös; fang mit der ersten Tatsache an“ mit „Maja ist vorbereitet und nervös; fang mit der ersten Tatsache an“. Harte Ich-Kritik mit freundlichem Rat über den Namen zu vergleichen verändert auch die Freundlichkeit. Damit lässt sich die Perspektive nicht isolieren. ODAs kurzer Rat mit anschließendem Satz ist eine Anpassung. Er entspricht weder dem Drei-Minuten-Verfahren noch einer Behandlung sozialer Angst."]},{heading:"Ein klarer Rat braucht weiterhin eine Gelegenheit",paragraphs:["Die kurzen Experimente belegen weder einen dauerhaften Nutzen noch ein vorgeschriebenes Pronomen oder einen allgemeinen Vorteil in jedem Umfeld. Gewohntes Denken in der Ich-Form ist nicht an sich schädlich. Vielleicht passt „Ich kann die Frage stellen“, eine neutrale Anweisung oder gar kein Nachdenken besser zu dir. Der fortlaufende Kursversuch betrifft weiterhin deine sinnvolle Aufgabe, nicht eine bestimmte grammatische Form deiner Selbstgespräche. (suggestion-S03)","Halte das echte Gespräch als Handlung fest, wenn es der nächste Aufgabenschritt ist. Bereitest du nur den Satz vor, notiere Vorbereitung und erfinde keine Teilnahme. Eine fehlende Gelegenheit darf als solche festgehalten werden. Anhaltende Belastung, starke Beeinträchtigung oder Selbstverletzungsgedanken erfordern fachliche Hilfe. Mit dem eigenen Namen nachzudenken ersetzt sie nicht. Schütze dich in unsicheren Situationen und nutze passende örtliche Unterstützung. Kein anderes Pronomen macht Missbrauch sicher oder hebt nötige Versorgung auf. (suggestion-S20)"]}],sourceIds:["suggestion-S03","suggestion-S20"]}},{schemaVersion:2,revision:2,id:"suggestion-5",courseId:"suggestion",locale:"de",title:"Fehler passiert? Benenne den nächsten Schritt",goal:"Wenn sich ein Fehler wiederholt, probiere eine konkrete Anweisung an einem echten Eintrag aus.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"Wieder ein Fehler, wieder ein Urteil über dich? Gib dem nächsten Versuch eine konkrete Anweisung.",reason:{id:"suggestion-5-reason",label:"Welches Urteil hat nach deinem letzten Fehler die tatsächliche Korrektur verzögert?",kind:"text",maxLength:160,optional:!0,suggestions:["„Ich bin nachlässig“; Datum nicht geändert","„Entwurf ist hoffnungslos“; Prüfung abgebrochen","Kein Urteil hat meine Korrektur verzögert","Noch kein Fehler; vielleicht urteile ich"],help:"Noch kein Fehler? Benenne ein Urteil, das die nächste Korrektur verzögern könnte."},why:{id:"suggestion-5-why",label:"Wofür würde dir dieser Schritt diese Woche Raum schaffen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Studien zu Selbstgesprächen im Sport fanden bei unterschiedlichen Aufgaben und Trainingsmethoden im Durchschnitt einen Leistungsvorteil. Anweisungen passten manchmal besser zu Präzisionsaufgaben. Die Vergleiche belegen aber weder einen allgemeinen Vorrang gegenüber Ermutigung noch denselben Effekt bei Büroarbeit.","Prüfe deinen Aufgabeneintrag. Benenne bei einem wiederkehrenden Detail die Anweisung: „Prüfe das Datum“. Probiere bei Bedarf erst ein einfaches Übungsbeispiel, dann einen echten Eintrag. Halte beides getrennt fest. Wenn du nicht weißt, wie du den Fehler korrigierst, bitte um Anleitung. Mehr Motivation liefert kein fehlendes Wissen und erledigt die Korrektur nicht."],example:{title:"Maja prüft das Datum",text:"Majas Bewerbungsentwurf enthält zwei widersprüchliche Daten. Beim Mittagssignal sagt sie „Prüfe das Datum“. Zur Vorbereitung übt sie an einem kopierten Beispiel. Dann prüft und berichtigt sie ein echtes Datum im Entwurf. Ein zweiter Widerspruch bleibt. Sie hält die Korrektur fest und bittet beim unklaren Eintrag um Anleitung. Sie behauptet nicht, die Anweisung habe alle Probleme im Entwurf gelöst."}},move:{invitation:"Behalte Eintrag und Startsignal bei. Die Vorschläge zeigen eine Datumskorrektur in der Bewerbung.",instructions:["Behalte Eintrag und Gelegenheit bei. Benenne die konkrete Anweisung zum Prüfen.","Nutze im Beispiel „Prüfe das Datum“ und berichtige einen Bewerbungseintrag.","Ist das Vorgehen unklar, wähle „Diesen Schritt anpassen“ und bitte um konkrete Anleitung."],prompts:[],suggestions:{action:["„Prüfe das Datum“ nutzen; einen Bewerbungseintrag berichtigen","Ein Bewerbungsdatum mit dem ursprünglichen Eintrag vergleichen"],minimum:["Ein berichtigtes Datum in der Bewerbung speichern","Festhalten, ob das Bewerbungsdatum stimmt"],cue:["Wenn die Mittagspause zu Ende ist","Wenn ich den Datumsabschnitt der Bewerbung erreiche"],place:["An meinem Küchentisch","Im Entwurf meiner Bewerbung"],minutes:[3,2,1],fallback:["Beim Gegenlesen fragen, wie ich das Datum prüfe","Den ursprünglichen Arbeitseintrag mit Datum prüfen"],observation:["Die tatsächliche Datumskorrektur oder Bitte um Anleitung","Das Übungsbeispiel getrennt von echter Arbeit"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"„Prüfe das Datum“ nutzen; einen Bewerbungseintrag berichtigen",minimum:"Ein berichtigtes Datum in der Bewerbung speichern",minutes:3,cueHint:"Wenn die Mittagspause zu Ende ist",placeHint:"An meinem Küchentisch",obstacleHint:"Ich weiß nicht, wie ich das richtige Datum prüfe",fallbackHint:"Beim Gegenlesen fragen, wie ich das Datum prüfe",observationHint:"Die tatsächliche Datumskorrektur oder Bitte um Anleitung"},stopRule:"Brauchst du Anleitung? Wähle „Diesen Schritt anpassen“, dann „Unterstützung“. Hole bei folgenreichen Aufgaben passenden fachlichen Rat.",accessibleAlternative:"Nutze eine schriftliche Anweisung, ein zugängliches Beispiel, Diktieren oder Hilfe."},result:{question:"Hast du einen echten Eintrag berichtigt oder um Anleitung gebeten?",observationPrompt:"Was hast du tatsächlich getan, und was stand im Weg?"},judgment:{primary:{id:"suggestion-5-decision",scenario:"Maja weiß, wie man ein Datum prüft, überspringt diesen Schritt aber wiederholt. Ein echter Eintrag in ihrer Bewerbung muss berichtigt werden.",question:"Was passt zu diesem Versuch?",options:[{id:"suggestion-5-drive",text:"Beim Erledigen der restlichen Einträge „Mach weiter“ nutzen, um in Schwung zu bleiben.",feedback:"Schwung zählt, aber dieser Eintrag zeigt eine ausgelassene Prüfung. Benenne dieses Detail und prüfe es an einem echten Eintrag, statt denselben Fehler durch die ganze Reihe mitzunehmen."},{id:"suggestion-5-detail",text:"Bei einem echten Eintrag „Prüfe das Datum“ nutzen und ihn dann berichtigen.",feedback:"Die Anweisung passt zum beobachteten Engpass und führt zu einer tatsächlichen Korrektur. Dieser persönliche Versuch zeigt dir, was passt. Er beweist nicht, dass die Anweisung die Wirkung verursacht hat."},{id:"suggestion-5-all",text:"Vor der Rückkehr zum Bewerbungseintrag eine kurze Checkliste für Daten, Bezeichnungen und Formatierung schreiben.",feedback:"Eine kurze Checkliste kann mehrere Lücken verhindern. Hier wurde eine Datumsprüfung ausgelassen, und Maja kennt das Vorgehen. Berichtige zuerst diesen echten Eintrag. Ergänze andere Prüfungen, wenn sie beobachteten Bedarf aufgreifen."}],bestOptionId:"suggestion-5-detail"}},carry:{takeaway:"Berichtige das nächste machbare Detail. Bitte um Anleitung, wenn dir die Fertigkeit fehlt.",followUp:{questionId:"suggestion-5-return",question:"Was ist mit der Korrektur oder Bitte um Anleitung passiert? Welches Detail braucht noch Prüfung?",observationPrompt:"Was zeigt dein tatsächlicher Eintrag?",adjustmentPrompt:"Was behältst oder änderst du beim nächsten Startsignal?"}},goDeeper:{sections:[{heading:"Ein Sportdurchschnitt verspricht keinen Büroerfolg",paragraphs:["Hatzigeorgiadis und Kollegen fassten in ihrer Meta-Analyse zweiunddreißig Studien und zweiundsechzig Effekte zusammen. Die Originaltabelle berichtete 2.741 Teilnehmende. Insgesamt betrug die korrigierte standardisierte Leistungsdifferenz 0,48, mit einem Konfidenzintervall von 0,38 bis 0,58. Untersucht wurden Sport- und Bewegungsaufgaben, auch mit Studierenden und Sportlern. Einige Studien hatten keine kontrollierten Vergleiche. Ein zusammengefasster Sportbefund bestimmt nicht, was in deinem Bewerbungsentwurf passiert oder welche Prüfregel du wählen solltest. (suggestion-S04)","Die Schätzungen unterschieden sich bei fein- und grobmotorischen Aufgaben, anleitenden und motivierenden Worten sowie vorherigem Training. Das sind keine randomisierten Vergleiche verschiedener Dosierungen und keine allgemeine Rangfolge der Techniken. Sie sagen keinen Vorteil von 0,48 für eine Tabelle, Bewerbung oder ein Gespräch voraus. Der heutige Versuch mit einer Anweisung und einem echten Eintrag ist eine ODA-Übertragung. Bleib bei einem guten Ergebnis bescheiden: Es zeigt, was bei diesem Eintrag geschah. Es zeigt weder warum noch, was jeder spätere Versuch bewirken wird."]},{heading:"Die Anweisung muss ein brauchbares Detail benennen",paragraphs:["Die Anweisung sollte das tatsächliche Problem deines Eintrags beantworten. „Prüfe das Datum“ benennt einen Schritt. „Sei hervorragend“ erklärt keine Korrektur. Ein einfaches Beispiel kann die Anweisung vorbereiten. Es erledigt aber den echten Eintrag nicht. Ist ein Vorgehen unbekannt, ist eine konkrete Bitte um Anleitung selbst eine sinnvolle Handlung. Die Sportübersicht validiert weder Gallweys gesamten Ansatz noch zwei getrennte Ichs im Gehirn oder ein ungeprüftes historisches Skript. (suggestion-S04)","Du kannst die Anweisung ändern, wenn sie nicht passt, nach einem machbaren Versuch beibehalten oder Selbstgespräche weglassen, wenn sie Druck machen. Füge nicht mehrere neue Anweisungen hinzu, nur damit der Plan beeindruckender wirkt. ODAs Eintrag hilft, den Engpass zu finden. Er bewertet nicht deinen Charakter. Anhaltende oder starke Belastung verlangt fachliche Unterstützung statt mehr Wiederholungen. (suggestion-S20)"]}],sourceIds:["suggestion-S04","suggestion-S20"]}},{schemaVersion:2,revision:2,id:"suggestion-6",courseId:"suggestion",locale:"de",title:"Planst du dich wach? Lass den Plan ruhen",goal:"Ist das Hindernis für morgen unklar, plane früher und halte den tatsächlichen Aufgabenversuch getrennt fest.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Die Ermutigung vorm Schlafen hält dich wach? Leg das Startsignal für morgen fest, solange du wach bist.",reason:{id:"suggestion-6-reason",label:"Was braucht einen Plan, und was braucht Erholung?",kind:"text",maxLength:160,optional:!0,suggestions:["Mittags zu viel los; anderes Tagessignal wählen","Plan steht; abendliches Kontrollieren beenden","Noch kein Planungsproblem beobachtet"]},why:{id:"suggestion-6-why",label:"Wofür würde dir dieser Schritt diese Woche Raum schaffen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Schlaf hilft, Erinnerungen zu verarbeiten. Das belegt kein besonderes Zeitfenster für Befehle ans Unterbewusstsein. Ergebnis, Hindernis und Reaktion gemeinsam zu planen hat Belege über verschiedene Ziele hinweg. Abendfantasie mit Planung erst am nächsten Morgen wurde dabei nicht geprüft.","Geh ein ungelöstes Hindernis früher an, solange du wach bist. Benenne gewünschtes Ergebnis, Hindernis und machbare Reaktion zusammen. Behalte denselben Aufgabenteil als Handlung bei. Planung ist Vorbereitung. Speichere und notiere den späteren Versuch getrennt. Hör mit dem Planen im Bett auf, wenn es dich wacher macht. Dein Plan braucht weder eine Szene noch Dankbarkeit oder Wiederholungen, um gültig zu sein."],example:{title:"Maja plant vorm Abendessen",text:"Um 18:30 Uhr plant Maja ihren Bewerbungssatz für morgen. Beim Frühstück erwartet sie viel Trubel. Sie wählt das Mittagssignal und eine Reaktion: den Satz diktieren, falls der Tisch belegt ist. Die Notiz ist Vorbereitung. Am nächsten Tag ist der Tisch belegt. Sie diktiert einen brauchbaren Satz und hält den Text fest. Im Bett lässt sie den Plan in Ruhe."}},move:{invitation:"Bleib bei deiner Aufgabe. Beispiel: Majas Schreiben tagsüber.",instructions:["Behalte Handlung, Minimum und Startsignal bei, sofern kein Hindernis eine Änderung verlangt.","Plane Ergebnis, Hindernis und Reaktion gemeinsam im Wachzustand. Halte die spätere Handlung getrennt fest."],prompts:[],suggestions:{action:["Nach dem Mittagessen einen Bewerbungssatz zur Erfahrung schreiben","Nach dem Mittagessen den Bewerbungssatz zur Erfahrung diktieren"],minimum:["Einen sachlichen Satz für die Bewerbung speichern","Einen diktierten Satz zur Arbeitserfahrung speichern"],cue:["Wenn die Mittagspause zu Ende ist","Nach meinem Getränk am Morgen"],place:["An meinem Küchentisch","Im Entwurf meiner Bewerbung"],minutes:[2,1,3],fallback:["Den Bewerbungssatz in der Mittagspause diktieren","Nach dem Abendessen den Satz zur Erfahrung schreiben"],observation:["Freier Tisch; Ausweichlösung bei Bedarf genutzt","Den tatsächlichen Bewerbungssatz nach der Vorbereitung"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Nach dem Mittagessen einen Bewerbungssatz zur Erfahrung schreiben",minimum:"Einen sachlichen Satz für die Bewerbung speichern",minutes:2,cueHint:"Wenn die Mittagspause zu Ende ist",placeHint:"An meinem Küchentisch",obstacleHint:"Mein Küchentisch ist belegt",fallbackHint:"Den Bewerbungssatz in der Mittagspause diktieren",observationHint:"Freier Tisch; Ausweichlösung bei Bedarf genutzt"},stopRule:"Beende Planung im Bett, wenn sie dich wacher macht. Erholung geht vor. Suche bei anhaltenden Problemen passende Hilfe.",accessibleAlternative:"Plane früher am Tag: tippen, sprechen oder Hilfe nutzen. Bilder bleiben freiwillig."},result:{question:"Hast du den tatsächlichen Teil beim Startsignal erarbeitet?",observationPrompt:"Was hast du tatsächlich getan, und was stand im Weg?"},judgment:{primary:{id:"suggestion-6-decision",scenario:"Maja hat einen schriftlichen Mittagsplan. Im Bett wird die Vorstellung von morgen zu wiederholtem ängstlichem Kontrollieren. Sie fühlt sich dadurch wacher.",question:"Was passt zu diesem Versuch?",options:[{id:"suggestion-6-finish",text:"Die Hindernisanalyse im Bett abschließen, damit der Plan für morgen sich vollständig geklärt anfühlt.",feedback:"Vollständigkeit ist verlockend. Ein machbarer Plan steht aber schon, und das Kontrollieren macht sie wacher. Hör jetzt auf. Prüfe nötige Änderungen früher, solange du wach bist."},{id:"suggestion-6-stop",text:"Die Szene beenden, das schriftliche Startsignal beibehalten und zur Erholung zurückkehren.",feedback:"Das schützt Erholung, ohne die machbare Handlung von morgen aufzugeben. Befunde zu Schlaf und Gedächtnis belegen kein nötiges Abendritual. Der spätere Aufgabenversuch bekommt seinen eigenen Eintrag."},{id:"suggestion-6-replace",text:"Die Szene durch einen wiederholten positiven Satz ersetzen, bis das Kontrollieren nachlässt.",feedback:"Ein anderes Ritual könnte dieselbe wache Anstrengung fortsetzen. Wiederholungen sind nicht nötig, damit der Plan gültig ist. Behalte das Startsignal bei und hör jetzt mit der Planung auf."}],bestOptionId:"suggestion-6-stop"}},carry:{takeaway:"Plane, solange du wach bist. Halte Erholung und die spätere Handlung getrennt fest.",followUp:{questionId:"suggestion-6-return",question:"Hat die Reaktion deine tatsächliche Handlung unterstützt, ohne den Aufwand im Bett zu verlängern?",observationPrompt:"Was zeigt dein tatsächlicher Eintrag?",adjustmentPrompt:"Was behältst oder änderst du beim nächsten Startsignal?"}},goDeeper:{sections:[{heading:"Schlafforschung bestätigt kein Selbsthilferitual",paragraphs:["Paller, Creery und Schechtmans Übersichtsarbeit behandelt die erneute Aktivierung bereits gelernter Inhalte im Schlaf und begrenztes Lernen einfacher Verknüpfungen. Es ist eine erzählende Zusammenschau ohne gemeinsamen Effektwert für Selbsthilfesuggestion. Gedächtnisverarbeitung belegt weder ein kritiklos empfängliches Unterbewusstsein vor dem Schlafen noch einen Vorteil für Bekräftigungen beim Eindösen oder komplexe Fähigkeiten durch einen Satz. Das sind verschiedene Behauptungen. (suggestion-S10)","Murphys Verlagsbeschreibung belegt die Herkunft des Buches und wirbt für Glauben und Vorstellungskraft. Sie belegt nicht, dass Murphys Abendritual funktioniert. Sie liefert keine kontrollierten Belege für das benannte Gesamtprogramm und validiert kein bestimmtes Wiederholungsskript. Macht Planung dich wacher, verlege nötige Planung auf eine frühere Gelegenheit tagsüber und lass die Schlafenszeit für Erholung frei. Ein freiwilliges Bild tagsüber bleibt eine ODA-Wahl. Es belegt weder Anziehung noch Heilung oder einen besonderen Mechanismus vorm Schlafen. (suggestion-S16)"]},{heading:"Betrachte Ergebnis, Hindernis und Reaktion zusammen",paragraphs:["Wang und Kollegen untersuchten in ihrer Meta-Analyse mentales Kontrastieren mit Wenn-dann-Plänen. Sie umfasste einundzwanzig Artikel, vierundzwanzig unabhängige Effekte und 15.907 Teilnehmende. Es gab im Durchschnitt einen Vorteil bei der Zielerreichung. Eine Korrektur möglicher Publikationsverzerrung senkte die Schätzung. Ziele, Methoden und Vergleiche unterschieden sich. Der Befund isoliert keinen positiven Satz als wirksamen Bestandteil und validiert nicht die zusammengesetzte ODA-Suggestionskarte. (suggestion-S06)","Nutze den Vergleich für eine konkrete Planungsfrage: Welches Ergebnis zählt, welches Hindernis ist wahrscheinlich und welche Reaktion ist machbar? Geh diese Teile zusammen durch. Speichere dann den tatsächlichen Aufgabenteil mit seinem Startsignal. Eine Notiz über morgen ist heutige Vorbereitung, nicht morgen bereits erledigte Arbeit. Verlangt das Hindernis Mittel, Sicherheit oder Hilfe, wähle diese praktische Reaktion, statt den Glauben verantwortlich zu machen. Frühere Planung schützt die Gelegenheit zur Erholung. Die Forschung prüfte keine Aufteilung in Abendfantasie und Planung am nächsten Morgen."]}],sourceIds:["suggestion-S10","suggestion-S16","suggestion-S06"]}},{schemaVersion:2,revision:2,id:"suggestion-7",courseId:"suggestion",locale:"de",title:"Zähle Handlungen, nicht das Lesen deiner Karte",goal:"Fasse die Einträge zu derselben Aufgabe zusammen und wähle den nächsten machbaren Versuch mit Anweisung und Handlung.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Erinnerung gelesen, Aufgabe nicht angerührt? Prüfe, was du tatsächlich erledigt hast, oder plane einen ersten Versuch.",reason:{id:"suggestion-7-reason",label:"Was behältst, änderst oder beendest du anhand deiner Einträge?",kind:"text",maxLength:160,optional:!0,suggestions:["Mittags ging es; Gelegenheit beibehalten","Morgens war Trubel; Startsignal ändern","Wiederholung machte Druck; Wiederholen beenden","Kein Versuch erfasst; erste Handlung wählen"]},why:{id:"suggestion-7-why",label:"Wofür würde dir dieser Schritt diese Woche Raum schaffen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ein glaubwürdiger Satz, Startsignal und Reaktion auf Hindernisse können zusammenpassen. Diese zusammengesetzte Karte wurde aber nicht als Gesamtprogramm validiert. Planungsforschung belegt nicht, dass das Lesen der Karte Handeln verursacht.","Prüfe deine Aufgabe oder wähle einen ersten Versuch. Unterscheide zwischen dem Lesen des Satzes, Vorbereitung, echten Handlungen und Rückblicken. Behalte passende Worte und ein machbares Signal bei. Ändere einen beobachteten Engpass. Speichere dieselbe Handlung mit demselben Minimum für die nächste Gelegenheit. Spätere Termine bleiben Pläne, bis du sie berichtest. Machen Worte Druck, vereinfache sie oder lass sie weg. Du brauchst weder Spiegel noch neues Ritual oder stärkeren Glauben."],example:{title:"Majas nächste Woche",text:"Am Sonntag sieht Maja fünf gelesene Erinnerungen und drei brauchbare Bewerbungsteile. Bei zwei verpassten Anfängen war morgens viel los; mittags ging es zweimal. Sie behält „Schreib die erste Tatsache auf“, lässt zusätzliche Bilder weg und plant den Montagsversuch mittags. Montag schreibt sie einen Satz, der noch Überarbeitung braucht. Sie notiert ihn. Die übrigen Termine bleiben Pläne."}},move:{invitation:"Behalte Handlung und Minimum. Die Vorschläge zeigen Bewerbungen.",instructions:["Behalte Handlung, Minimum, Startsignal und Ort bei. Ändere nur den beobachteten Engpass.","Ohne Eintrag: Benenne vor dem Speichern eine erste Handlung und ihr passendes Minimum.","Nutze „Diesen Schritt anpassen“ für eine Unterstützungsbitte. Spätere Termine bleiben Pläne."],prompts:[],suggestions:{action:["„Prüfe das Datum“ nutzen; einen Bewerbungseintrag berichtigen","Ein Bewerbungsdatum mit dem ursprünglichen Eintrag vergleichen"],minimum:["Ein berichtigtes Datum in der Bewerbung speichern","Festhalten, ob das Bewerbungsdatum stimmt"],cue:["Wenn die Mittagspause zu Ende ist","Wenn ich den Datumsabschnitt der Bewerbung erreiche"],place:["An meinem Küchentisch","Im Nachrichtenverlauf zum Bewerbungscheck"],minutes:[2,1,3],fallback:["Lesen beenden; ein Bewerbungsdatum überprüfen","Nachfragen, welche Quelle für das Datum passt"],observation:["Tatsächliche Korrekturen getrennt vom Lesen der Karte","Ob Mittagsgelegenheit und Anweisung passten"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"„Prüfe das Datum“ nutzen; einen Bewerbungseintrag berichtigen",minimum:"Ein berichtigtes Datum in der Bewerbung speichern",minutes:2,cueHint:"Wenn die Mittagspause zu Ende ist",placeHint:"An meinem Küchentisch",obstacleHint:"Ich lese weiter, statt das Bewerbungsdatum zu prüfen",fallbackHint:"Lesen beenden; ein Bewerbungsdatum überprüfen",observationHint:"Tatsächliche Korrekturen getrennt vom Lesen der Karte"},stopRule:"Für Hilfe bei der Aufgabe wähle „Diesen Schritt anpassen“, dann „Unterstützung“. Lass belastende Worte weg. Suche bei anhaltender Belastung oder Beeinträchtigung fachliche Hilfe. Behalte verordnete Behandlungen bei.",accessibleAlternative:"Nutze eine private zugängliche Notiz, neutrale Worte oder Hilfe. Ein Spiegel ist nicht nötig."},result:{question:"Hast du den nächsten Teil oder die gewählte Unterstützungsaktion erledigt?",observationPrompt:"Was hast du tatsächlich getan, und was stand im Weg?"},judgment:{primary:{id:"suggestion-7-decision",scenario:"Maja las ihre Karte täglich, schrieb aber nur einmal mittags. Morgens war viel los. Die Anweisung fühlte sich weiterhin glaubwürdig an.",question:"Was passt zu diesem Versuch?",options:[{id:"suggestion-7-repeat",text:"Den Morgenplan beibehalten, weil das tägliche Lesen der Karte zeigt, dass die Routine schon greift.",feedback:"Tägliches Lesen lässt sich ehrlich festhalten, ist aber noch kein geschriebener Bewerbungssatz. Ihr Signal führte selten zur Arbeit. Probiere stattdessen die verfügbare Mittagspause."},{id:"suggestion-7-increase",text:"Abends zusätzlich lesen, damit sie sich leichter an den glaubwürdigen Satz erinnern kann.",feedback:"Erinnern kann helfen. Die vorhandenen Hinweise zeigen aber, dass morgens zu viel los war. Mehr Lesen ändert die Wiederholung und lässt das Aufgabensignal gleich. Prüfe zuerst den beobachteten Engpass."},{id:"suggestion-7-revise",text:"Den glaubwürdigen Satz behalten, die Mittagspause nutzen und einen tatsächlichen Teil zum Schreiben planen.",feedback:"Das behält bei, was passt, und ändert das Signal bei verpassten Anfängen. Der nächste Teil bleibt ein Plan, bis sie ihn berichtet. Nutze den morgigen Rückblick, um den neuen Versuch zu prüfen."}],bestOptionId:"suggestion-7-revise"}},carry:{takeaway:"Behalte hilfreiche Worte mit einer machbaren Handlung, ehrlichem Eintrag und nächster Entscheidung bei.",followUp:{questionId:"suggestion-7-return",question:"Was ist bei deiner Handlung oder Unterstützungsbitte passiert, und was muss sich ändern?",observationPrompt:"Was zeigt dein tatsächlicher Eintrag?",adjustmentPrompt:"Was behältst oder änderst du beim nächsten Startsignal?"}},goDeeper:{sections:[{heading:"Die zusammengesetzte Karte ist eine Gestaltungsentscheidung",paragraphs:["Der Kurs verbindet glaubwürdige Worte, ein Startsignal, einen echten Aufgabenteil, eine Reaktion auf Hindernisse und einen Rückblickeintrag. Diese Kombination stammt von ODA. Sie ist kein kontrolliert untersuchtes Interventionspaket. Wang und Kollegen stützen mit ihrer Übersichtsarbeit mentales Kontrastieren mit Wenn-dann-Plänen bei unterschiedlichen Zielen. Sie belegen aber weder den Nutzen jedes Bestandteils der Karte noch, dass das Lesen der Karte eine erledigte Aufgabe verursacht hat. (suggestion-S06)","Nutze die Karte als knappe Erinnerung an deinen gespeicherten Plan, nicht als neue Pflicht. Prüfe Vorbereitung getrennt vom brauchbaren Teil. Du kannst das Lesen der Karte ehrlich berichten, ohne es als Schreiben, Fragen oder Korrigieren zu zählen. Behalte einen beobachteten Engpass im Blick, damit der nächste Versuch eine konkrete Frage beantwortet. Ein guter persönlicher Eintrag ist Rückmeldung zur Passung. Er ist weder Ursachenbeweis noch Garantie, dass derselbe Plan in jeder Woche klappt."]},{heading:"Am Ende brauchst du kein neues Ritual",paragraphs:["Lallys Beobachtungsstudie zu Gewohnheiten betraf Essen, Trinken und Bewegung bei wiederkehrenden Signalen. Sie prüfte keine positiven Sätze und garantierte keine Frist für die Automatisierung. ODAs Gelegenheiten für nächste Woche und der Rückblickabstand helfen, deinen Versuch zu ordnen. Sie sind keine getestete Dosis und verlangen keine lückenlose Serie. Tatsächliche Aufgabenversuche bleiben getrennt vom Abschluss der Lernlektionen. (suggestion-S09)","Hays Website beschreibt Spiegelsätze und ein Programm über einundzwanzig Tage. Die Evidenzrecherche fand keine kontrollierte Studie zu diesem benannten Gesamtprogramm. Das beweist nicht, dass es nie untersucht wurde. Für den Spiegel ist hier kein Vorrang belegt, und einundzwanzig Tage sind keine Gewohnheitsfrist. Eine private Notiz, eine zugängliche Erinnerung oder gar keine Karte können zu dir passen. Führe zum Abschluss dieselbe sinnvolle Aufgabe weiter. Passe sie anhand deiner Einträge an. Schütze Sicherheit, Erholung und verordnete Versorgung. (suggestion-S18)"]}],sourceIds:["suggestion-S06","suggestion-S09","suggestion-S18"]}}],r=[{id:"suggestion-1",practice:["Benenne eine Alltagssituation, die du diese Woche anders angehen möchtest.","Vergleiche den gewohnten kritischen Satz mit einer glaubwürdigen neutralen Anweisung. Bilder und Ermutigung bleiben freiwillig.","Probiere die Anweisung mit einem sinnvollen Aufgabenteil. Halte die tatsächliche Handlung und möglichen Druck getrennt fest."],reflection:"Welchen Satz sagst du dir am häufigsten, und wie wirkt er auf dich?",question:"Wie wird Suggestion in diesem Kurs verstanden?",options:["Ein geheimer Befehl ans Unterbewusstsein, der von selbst alles verändert.","Einen gewählten Satz, ein Bild und eine kleine Handlung zusammen wiederholen.","Eine Denktechnik, die Medikamente oder Behandlung ersetzen kann."],correct:1,feedback:"Der Kurs nutzt einen ungeprüften Versuch mit Anweisung und Handlung. Bilder sind freiwillig. Klinische Erwartungsstudien validieren die zusammengesetzte Routine nicht. Suggestion ersetzt keine Behandlung und garantiert keine äußeren Ergebnisse.",photo:{id:"1461468611824-46457c0e11fd",alt:"Eine Frau sitzt und schaut aufs Meer"}},{id:"suggestion-2",practice:["Wenn du Coués historisches Ritual kennenlernen möchtest, prüfe, ob die Worte für dich passen. Zählhilfen sind freiwillig.","Sein englischer Text von 1922 beschrieb zwanzig leise Wiederholungen. Das ist Geschichte, keine bewiesene Dosis oder nötige Abendpraxis.","Probierst du Worte freiwillig aus, höre bei Belastung oder Wachheit auf. Trenne das Satzlesen von tatsächlicher Arbeit an der Aufgabe."],reflection:"Wie fühlte sich die Formel ohne Anstrengung an: beruhigend, seltsam oder langweilig?",question:"Was passt zu der Haltung, die Coué für seine Formel empfahl?",options:["Den Satz mit zusammengebissenen Zähnen so kraftvoll wie möglich sagen.","Den Satz entspannt und leise sagen. Die Schnur oder Perlen übernehmen das Zählen.","Nach jeder Wiederholung prüfen, ob sich etwas verändert hat."],correct:1,feedback:"Coué empfahl historisch entspanntes Wiederholen. Anekdoten belegen weder ein allgemeines Gesetz zur Vorstellungskraft noch eine wirksame Dosis von zwanzig Wiederholungen oder Heilung. Die gelesene englische Ausgabe stammt von 1922.",photo:{id:"1762328490563-9b9c300fba3e",alt:"Eine Person hält eine Perlenschnur"}},{id:"suggestion-3",practice:["Wähle einen positiven Satz oder eine neutrale Aufgabenanweisung, die für dich passt.","Schätze die Glaubwürdigkeit freiwillig für deine Wortwahl ein, ohne klinische Schwelle. Ändere belastende Worte oder höre auf.","Denke freiwillig über einen wichtigen Wert nach. Wähle dann eine konkrete Handlung für die Aufgabe, die dazu passt."],reflection:"Bei welchem Satz denkst du: „Ja, das könnte stimmen“?",question:"Welche Worte kannst du angesichts gemischter Befunde zu positiven Selbstsätzen ausprobieren?",options:["Den kühnsten Satz häufiger wiederholen, selbst wenn du ihm nicht glaubst.","Einen glaubwürdigen Satz wählen, der ein Vorgehen beschreibt.","Niemals einen positiven Satz zu dir sagen."],correct:1,feedback:"Der frühe Bericht schlechterer Reaktionen wurde in zwei späteren Studien nicht wiedergefunden. Neutrale oder handlungsbezogene Worte sind eine freiwillige Vorliebe, keine nachweislich sicherere Behandlung. Glaubwürdigkeitswerte diagnostizieren kein Selbstwertgefühl.",photo:{id:"1616628188467-8fb29f49bbe8",alt:"Eine Hand schreibt eine Notiz auf weißes Papier"}},{id:"suggestion-4",practice:["Wähle einen schwierigen Moment dieser Woche und halte seine Zeit fest.","Beschreibe dir davor zwei Minuten lang die Situation. Sprich dich dabei mit deinem Namen an.","Sag dir dann den unterstützenden Satz, den du einem Freund in derselben Situation sagen würdest."],reflection:"Wie änderte sich dein Ton, als du dich mit deinem Namen angesprochen hast?",question:"Welche Selbstgespräche halfen in Kross' Experimenten von 2014 bei sozialem Stress eher?",options:["Sich mit dem eigenen Namen oder „du“ ansprechen.","Lange über die Situation nachdenken und nur „ich“ nutzen.","Sich mit harter Kritik motivieren."],correct:0,feedback:"Kurze Experimente mit sozialem Stress fanden bessere Gesprächsleistung aus Beobachtersicht beim Nachdenken mit Namen oder ohne Ich-Perspektive. Studie 2 verringerte Angst vor dem Gespräch nicht signifikant; Erholung danach war deutlicher. Das ist keine Behandlung.",photo:{id:"1641907173006-6b8930ae1191",alt:"Eine Frau blickt nachdenklich zum Himmel"}},{id:"suggestion-5",practice:["Wähle eine Aufgabe dieser Woche, die du schwer zu lernen oder gut zu erledigen findest.","Schreibe dafür ein anleitendes und ein motivierendes Stichwort auf.","Wiederhole beim Arbeiten die Anweisung kurz mit ruhiger Stimme. Halte das Ergebnis ohne Bewertung fest."],reflection:"Welche Anweisung hat deine Aufmerksamkeit tatsächlich zur Aufgabe gelenkt?",question:"Wann halfen anleitende Selbstgespräche laut Meta-Analyse besonders gut?",options:["Bei Aufgaben, die feine Fertigkeiten und Aufmerksamkeit brauchen.","Nur bei sehr gut eingeübten, automatischen Aufgaben.","Nur beim ersten Versuch, ganz ohne Übung."],correct:0,feedback:"In Sportstudien passten Anweisungen oft zu feinen oder neuen Aufgaben. Einige Studien hatten keine Kontrollgruppe. Aufgaben- und Trainingsvergleiche belegen weder eine allgemeine Rangfolge noch optimale Dosis oder gleichwertigen Nutzen bei Büroarbeit.",photo:{id:"1523497804259-88c4c134ca90",alt:"Ein Sportler bereitet sich auf einer Laufbahn aufs Laufen vor"}},{id:"suggestion-6",practice:["Benenne früher am Tag im Wachzustand dein gewünschtes Ergebnis und ein echtes Hindernis zusammen.","Wähle eine machbare Reaktion und einen sinnvollen tatsächlichen Aufgabenteil. Freiwillige Bilder bleiben Vorbereitung.","Speichere das Startsignal der Aufgabe und halte den späteren Versuch getrennt fest. Beende Abendplanung, wenn sie dich wacher macht."],reflection:"Woran hat dich die Szene vor dem Schlafen am Morgen erinnert?",question:"Welche Vorbereitung hält die Suggestionsaussagen innerhalb der Belege?",options:["Das Ergebnis vorstellen und das echte Hindernis sowie einen Wenn-dann-Plan ergänzen.","Warten, bis das Unterbewusstsein im Schlaf von selbst Geld und Gesundheit anzieht.","Nur das gute Ergebnis vorstellen und gar nichts planen."],correct:0,feedback:"Planung mit Ergebnis, Hindernis und Reaktion hat Belege bei unterschiedlichen Zielen. Das validiert weder ein besonderes Eindösritual noch Abendfantasie mit Planung erst am nächsten Morgen. Schütze Schlaf. Die spätere Handlung bleibt getrennt.",photo:{id:"1757796859729-270d1e3ad4d5",alt:"Ein offenes Buch auf dem Nachttisch unter einer leuchtenden Lampe"}},{id:"suggestion-7",practice:["Wenn eine Karte hilft, notiere eine glaubwürdige Anweisung und freiwillig ein Bild des ersten Schritts. Nutze ein privates zugängliches Format.","Ergänze das tatsächliche Startsignal und eine machbare Hindernisreaktion. Die Karte zu lesen erledigt die Aufgabe nicht.","Wähle einen Rückblicktermin. Vergleiche danach echte Versuche mit Vorbereitung, sobald sie stattgefunden haben. Eine Woche ist keine validierte Dosis."],reflection:"Was würdest du auf deiner Karte nach sieben Tagen genauso behalten, und was ändern?",question:"Welcher Umgang hilft am meisten, wenn du deine Suggestionskarte nach sieben Tagen prüfst?",options:["Dir Vorwürfe machen, wenn sich nichts verändert hat.","Prüfen, was funktioniert hat, und Satz, Bild oder Plan anpassen.","Einen kühneren Satz lauter sagen."],correct:1,feedback:"Prüfe echte Aufgabenversuche getrennt vom Lesen der Karte. Die zusammengesetzte Karte ist ungeprüft. Behalte hilfreiche Worte und ändere einen beobachteten Engpass. Spiegel, stärkerer Glaube und ein neues Ritual sind nicht nötig.",photo:{id:"1484480974693-6ca0a78fb36b",alt:"Eine Hand schreibt eine Checkliste in ein Notizbuch"}}],s={lang:"de",id:"suggestion",title:"Innere Kritik bremst? Gib ihr eine Aufgabe",subtitle:"Sieben kurze Lektionen. Nutze glaubwürdige Worte für eine sinnvolle Handlung. Passe sie danach an das an, was tatsächlich passiert ist.",description:"Wähle eine bedeutsame Aufgabe und probiere eine glaubwürdige Anweisung zusammen mit echter Handlung aus. Verbessere ihr Startsignal, nutze Rückmeldung, geh ein beobachtetes Hindernis an und führe denselben Versuch nächste Woche weiter.",scope:"Ein Kurs zu Selbstsuggestion und Selbstgesprächen für Erwachsene. Er ist weder Hypnotherapie noch Diagnose oder Behandlung. Suggestion ersetzt keine Medikamente oder laufende Behandlung. Setze Medikamente oder eine Behandlung nicht ohne Gespräch mit deinem Arzt ab. Manche Bücher behaupten, Suggestion heile Krankheiten oder ziehe Geld an. Die Forschung stützt diese Aussagen nicht. Sind deine inneren negativen Sätze sehr intensiv oder fühlst du dich schon lange niedergeschlagen, suche fachliche Unterstützung für psychische Gesundheit. Hast du Gedanken, dir etwas anzutun, oder bist du in unmittelbarer Gefahr, rufe die örtliche Notrufnummer an.",outcome:"Eine glaubwürdige Anweisung für eine sinnvolle Aufgabe, ein ehrlicher Handlungseintrag und ein nächster Versuch, der sich an deinem tatsächlichen Tag orientiert.",photo:{id:"1779922811108-245a9403ef44",alt:"Der Umriss einer Person auf einem Hügel im Morgengrauen"},lessons:n.map((e,i)=>({...r[i],schemaVersion:2,v2:e,title:e.title,goal:e.goal,minutes:e.minutes.learning,reading:e.idea.paragraphs,example:e.idea.example,deeper:e.goDeeper.sections,sources:[...new Set([...e.goDeeper.sourceIds,"suggestion-S20",...e.id==="suggestion-3"?["suggestion-S07","suggestion-S08"]:[]])],takeaway:e.carry.takeaway,visual:{kind:"steps",title:"Ein fortlaufender Versuch",steps:[{label:"Startsignal",text:"Wähle eine machbare Gelegenheit."},{label:"Handeln",text:"Probiere dein sinnvolles Minimum."},{label:"Rückblick",text:"Halte fest und wähle den nächsten Versuch."}]}}))},a=Object.freeze(Object.defineProperty({__proto__:null,COURSE:s,SOURCES:t,SUGGESTION_LESSONS_V2:n},Symbol.toStringTag,{value:"Module"}));export{a as s};
